window.MG_LAZY_DATA["data/lazy/courses/b103-c86bf860753e69d0.json"]={sha256:"c86bf860753e69d063194c8b7f460c4422eb1a3660fd1875c01d074bfb722d88",value:{"id":"b103","category":"underground","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical","v10-other-vendor-b103"],"title":"哥達基線隧道","titleEn":"Gotthard Base Tunnel","summary":"沿 24 個判讀步驟研究阿爾卑斯基線鐵路的路線、地質、施工物流、防水與鐵路系統整合；以可查證的證據代替想像中的挖掘配方。","summaryEn":"Study alignment, geology, construction logistics, waterproofing and railway integration of an Alpine base tunnel through 24 evidence-led exercises.","scope":"以公開一次資料為背景的原創工程判讀課程；每步在紙上或數位示意模型中完成。自設數值、構形與工序不得當成原工程的設計、施工、設備操作或驗收程序。","scopeEn":"Original engineering interpretation exercises grounded in public primary sources. Complete each step on paper or in a schematic digital model. Invented values, geometry and sequences are not the original project’s design, construction, operating or acceptance procedures.","diagram":{"type":"tunnel","labels":["需求與場址","結構與介面","施工狀態","驗證與維護"],"labelsEn":["Requirements and site","Structures and interfaces","Construction states","Verification and maintenance"],"original":true,"notToScale":true},"stepCount":24,"estimatedMinutes":600,"stages":[{"id":"b103-stage01","order":1,"title":"路線、地質與不確定性","titleEn":"Alignment, geology and uncertainty","description":"以六個相互銜接的練習完成「路線、地質與不確定性」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on alignment, geology and uncertainty, retaining assumptions, diagrams and evidence.","steps":[{"id":"b103-v7-01","sequence":1,"order":1,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":[],"title":"把基線路線放回鐵路網","titleEn":"Place the base alignment in its network","objective":"理解隧道長度以外的運輸目的。","objectiveEn":"Understand the transport purpose beyond tunnel length.","instruction":"1. 畫跨山舊線與概念基線；2. 分列坡度、距離及連接路段；3. 指出一個仍可能限制全線容量的外部瓶頸。","instructionEn":"1. Sketch the mountain route and conceptual base route; 2. separate gradient, distance and connecting sections; 3. identify an external bottleneck that could still limit capacity.","observation":"隧道本身能力提高不會自動消除連接鐵路的瓶頸。","observationEn":"Improved tunnel capability does not automatically remove bottlenecks on connecting railways.","failure":"只要隧道更長就一定使整條運輸走廊更有效率。","failureEn":"A longer tunnel necessarily makes the entire transport corridor more efficient.","check":"繳交含兩端連接線的需求圖。","checkEn":"Provide a requirements map including both connecting routes.","knowledge":[{"id":"b103-v7-01-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"基線路線以較低高程穿越山體，坡度及路線條件影響列車牽引與運輸安排。","textEn":"A base route crosses at a lower elevation; gradients and alignment affect traction and transport planning."},{"id":"b103-v7-01-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"官方長度及運輸背景是比較起點，不能直接用來計算今天的班表能力。","textEn":"Official length and transport context begin the comparison but do not directly determine present timetable capacity."}],"quiz":{"question":"審查「把基線路線放回鐵路網」時，哪個判讀有根據？","questionEn":"When reviewing “Place the base alignment in its network”, which interpretation is justified?","options":["隧道本身能力提高不會自動消除連接鐵路的瓶頸。","只要隧道更長就一定使整條運輸走廊更有效率。","增加一段隧道的能力就保證所有連接路段同步增加能力。"],"optionsEn":["Improved tunnel capability does not automatically remove bottlenecks on connecting railways.","A longer tunnel necessarily makes the entire transport corridor more efficient.","Increasing one tunnel’s capacity guarantees matching gains on all connecting routes."],"answer":0,"explanation":"基線路線以較低高程穿越山體，坡度及路線條件影響列車牽引與運輸安排。 官方長度及運輸背景是比較起點，不能直接用來計算今天的班表能力。","explanationEn":"A base route crosses at a lower elevation; gradients and alignment affect traction and transport planning. Official length and transport context begin the comparison but do not directly determine present timetable capacity."}},{"id":"b103-v7-02","sequence":2,"order":2,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-01"],"title":"分開雙管與連通設施","titleEn":"Separate running tubes and connections","objective":"辨認列車路徑與橫向連通功能。","objectiveEn":"Distinguish train paths from transverse connections.","instruction":"1. 畫兩條單線主隧道；2. 用不同符號標示橫坑及多功能區；3. 分開列車通道與人員通行的概念圖例。","instructionEn":"1. Draw two single-track running tubes; 2. mark cross-passages and multifunction areas with different symbols; 3. separate train paths from conceptual pedestrian connections.","observation":"兩條主隧道與橫坑具有不同功能，不能都視為可行車路線。","observationEn":"Running tubes and cross-passages have different functions and are not all train routes.","failure":"圖上只要連通就能讓列車任意從一管換到另一管。","failureEn":"Any connection drawn between tubes permits trains to change tubes there.","check":"提供至少三種連通功能的圖例。","checkEn":"Provide a legend distinguishing at least three connection functions.","knowledge":[{"id":"b103-v7-02-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"交通路徑、設備空間與逃生連通各有不同幾何及系統需求。","textEn":"Traffic paths, equipment spaces and escape connections have different geometric and system requirements."},{"id":"b103-v7-02-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"示意圖的連線不等於具備軌道、控制或可使用狀態。","textEn":"A connecting line in a schematic does not establish track, control or availability."}],"quiz":{"question":"審查「分開雙管與連通設施」時，哪個判讀有根據？","questionEn":"When reviewing “Separate running tubes and connections”, which interpretation is justified?","options":["圖上只要連通就能讓列車任意從一管換到另一管。","兩條主隧道與橫坑具有不同功能，不能都視為可行車路線。","所有橫坑都具有列車軌道及轉轍功能。"],"optionsEn":["Any connection drawn between tubes permits trains to change tubes there.","Running tubes and cross-passages have different functions and are not all train routes.","Every cross-passage contains tracks and train-switching functions."],"answer":1,"explanation":"交通路徑、設備空間與逃生連通各有不同幾何及系統需求。 示意圖的連線不等於具備軌道、控制或可使用狀態。","explanationEn":"Traffic paths, equipment spaces and escape connections have different geometric and system requirements. A connecting line in a schematic does not establish track, control or availability."}},{"id":"b103-v7-03","sequence":3,"order":3,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-02"],"title":"建立地質預測與實證兩欄","titleEn":"Separate predicted geology from observations","objective":"把地質模型當成需持續更新的假說。","objectiveEn":"Treat the geological model as a hypothesis requiring updates.","instruction":"1. 畫含三種自設岩性區的縱斷面；2. 另列鑽孔與掌子面觀察欄；3. 將未驗證區段以虛線保留。","instructionEn":"1. Draw a longitudinal section with three hypothetical rock zones; 2. separate borehole and face observations; 3. keep unverified sections dashed.","observation":"地質預測必須隨新觀察更新，不能等同沿線已完全確認。","observationEn":"Geological predictions need updating with observations and do not establish complete route knowledge.","failure":"已有一張縱斷面就表示兩個鑽孔之間的岩體全部已證實。","failureEn":"One section drawing verifies every rock volume between two boreholes.","check":"提交預測、觀察與信心水準分開的剖面。","checkEn":"Submit a section separating predictions, observations and confidence.","knowledge":[{"id":"b103-v7-03-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"鑽孔只直接觀察有限空間，向外延伸的解釋具有不確定性。","textEn":"Boreholes directly sample limited space; extrapolated interpretations carry uncertainty."},{"id":"b103-v7-03-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"工程判讀重點是預測與實際差異如何影響模型，而非把地層畫得整齊。","textEn":"Engineering interpretation asks how prediction–observation differences affect the model, not how tidy the strata look."}],"quiz":{"question":"審查「建立地質預測與實證兩欄」時，哪個判讀有根據？","questionEn":"When reviewing “Separate predicted geology from observations”, which interpretation is justified?","options":["已有一張縱斷面就表示兩個鑽孔之間的岩體全部已證實。","鑽孔間的地層圖是直接觀察全部地下空間的紀錄。","地質預測必須隨新觀察更新，不能等同沿線已完全確認。"],"optionsEn":["One section drawing verifies every rock volume between two boreholes.","A section between boreholes directly records the entire underground volume.","Geological predictions need updating with observations and do not establish complete route knowledge."],"answer":2,"explanation":"鑽孔只直接觀察有限空間，向外延伸的解釋具有不確定性。 工程判讀重點是預測與實際差異如何影響模型，而非把地層畫得整齊。","explanationEn":"Boreholes directly sample limited space; extrapolated interpretations carry uncertainty. Engineering interpretation asks how prediction–observation differences affect the model, not how tidy the strata look."}},{"id":"b103-v7-04","sequence":4,"order":4,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-03"],"title":"解讀斷層與破碎帶","titleEn":"Interpret faults and fractured zones","objective":"辨識岩石種類與岩體結構的不同。","objectiveEn":"Distinguish rock type from rock-mass structure.","instruction":"1. 用同一岩性畫完整及節理密集兩模型；2. 標出節理方向與水的可能路徑；3. 比較需要補充的觀察資料。","instructionEn":"1. Draw intact and heavily jointed examples of the same rock type; 2. mark joint directions and possible water paths; 3. compare required observations.","observation":"相同岩石名稱可能對應不同節理、水文及變形條件。","observationEn":"The same rock name may conceal different jointing, groundwater and deformation conditions.","failure":"只知道岩石硬度即可選定所有支護需求。","failureEn":"Rock hardness alone determines every support requirement.","check":"繳交岩性、構造與含水條件的分欄表。","checkEn":"Provide separate fields for lithology, structure and groundwater.","knowledge":[{"id":"b103-v7-04-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"岩體行為不只由完整岩塊強度決定，也受不連續面與水影響。","textEn":"Rock-mass behavior depends on discontinuities and water as well as intact-rock strength."},{"id":"b103-v7-04-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本步不提供支護尺寸或挖掘設定，而是建立需由地質證據回答的問題。","textEn":"This step gives no support dimensions or excavation settings; it defines questions requiring geological evidence."}],"quiz":{"question":"審查「解讀斷層與破碎帶」時，哪個判讀有根據？","questionEn":"When reviewing “Interpret faults and fractured zones”, which interpretation is justified?","options":["相同岩石名稱可能對應不同節理、水文及變形條件。","只知道岩石硬度即可選定所有支護需求。","完整岩塊的強度可以取代節理與地下水資料。"],"optionsEn":["The same rock name may conceal different jointing, groundwater and deformation conditions.","Rock hardness alone determines every support requirement.","Intact-rock strength replaces joint and groundwater information."],"answer":0,"explanation":"岩體行為不只由完整岩塊強度決定，也受不連續面與水影響。 本步不提供支護尺寸或挖掘設定，而是建立需由地質證據回答的問題。","explanationEn":"Rock-mass behavior depends on discontinuities and water as well as intact-rock strength. This step gives no support dimensions or excavation settings; it defines questions requiring geological evidence."}},{"id":"b103-v7-05","sequence":5,"order":5,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-04"],"title":"辨認覆土、地應力與溫度","titleEn":"Distinguish cover, stress and temperature","objective":"避免用單一深度數字概括地下條件。","objectiveEn":"Avoid reducing underground conditions to one depth number.","instruction":"1. 在斷面分別標示地表及隧道標高；2. 畫假想覆土變化；3. 將應力、熱與地下水證據列成不同需求。","instructionEn":"1. Mark surface and tunnel elevations separately; 2. draw hypothetical cover variation; 3. list separate stress, heat and groundwater evidence needs.","observation":"覆土深度增加不等於所有位置具有同樣應力方向或水壓。","observationEn":"Greater cover does not imply identical stress directions or water pressures everywhere.","failure":"地表到隧道的距離可以直接替代完整地應力與水文資料。","failureEn":"Surface-to-tunnel distance replaces complete stress and hydrogeological information.","check":"提交三類環境條件及各自需量測的資料。","checkEn":"Submit three environmental conditions with their measurement needs.","knowledge":[{"id":"b103-v7-05-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"地形、構造歷史與岩體性質會使應力場偏離簡單垂直自重估算。","textEn":"Topography, tectonic history and rock properties can make stress fields differ from simple overburden estimates."},{"id":"b103-v7-05-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"熱、水與力學資料具有不同量測方法，不能因共用一張剖面就互相代替。","textEn":"Thermal, hydraulic and mechanical conditions require different observations despite sharing a section drawing."}],"quiz":{"question":"審查「辨認覆土、地應力與溫度」時，哪個判讀有根據？","questionEn":"When reviewing “Distinguish cover, stress and temperature”, which interpretation is justified?","options":["地表到隧道的距離可以直接替代完整地應力與水文資料。","覆土深度增加不等於所有位置具有同樣應力方向或水壓。","熱環境與水壓可從覆土深度唯一決定。"],"optionsEn":["Surface-to-tunnel distance replaces complete stress and hydrogeological information.","Greater cover does not imply identical stress directions or water pressures everywhere.","Cover depth uniquely determines temperature and water pressure."],"answer":1,"explanation":"地形、構造歷史與岩體性質會使應力場偏離簡單垂直自重估算。 熱、水與力學資料具有不同量測方法，不能因共用一張剖面就互相代替。","explanationEn":"Topography, tectonic history and rock properties can make stress fields differ from simple overburden estimates. Thermal, hydraulic and mechanical conditions require different observations despite sharing a section drawing."}},{"id":"b103-v7-06","sequence":6,"order":6,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-05"],"title":"制定勘察更新的決策紀錄","titleEn":"Create an investigation-update decision record","objective":"讓新地質證據影響後續模型。","objectiveEn":"Make new geological evidence propagate into downstream models.","instruction":"1. 設定一個與預測不同的假想觀察；2. 列出受影響的支護、物流與防水問題；3. 標記哪些結論需重做而哪些仍有效。","instructionEn":"1. Introduce a hypothetical observation inconsistent with prediction; 2. list affected support, logistics and waterproofing questions; 3. mark conclusions needing revision and those still valid.","observation":"新證據的價值在修正相依判斷，不能只新增一張地質照片。","observationEn":"New evidence should revise dependent judgments rather than merely add a geological photograph.","failure":"把差異記錄存檔後即可繼續沿用全部舊假設。","failureEn":"Filing a discrepancy permits all old assumptions to remain unchanged.","check":"繳交一份有上游證據及下游影響的變更單。","checkEn":"Provide a change record linking upstream evidence to downstream impacts.","knowledge":[{"id":"b103-v7-06-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"觀測與決策之間需要明確連結，否則資料很多也無法降低模型風險。","textEn":"Observations need explicit links to decisions; more data alone do not reduce modeling risk."},{"id":"b103-v7-06-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"未知條件可導致暫停判斷與補資料，這是工程品質控制的一部分。","textEn":"Unknown conditions can require pausing a judgment and gathering evidence as part of quality control."}],"quiz":{"question":"審查「制定勘察更新的決策紀錄」時，哪個判讀有根據？","questionEn":"When reviewing “Create an investigation-update decision record”, which interpretation is justified?","options":["把差異記錄存檔後即可繼續沿用全部舊假設。","地質模型一旦發布就不應因新觀察而修改。","新證據的價值在修正相依判斷，不能只新增一張地質照片。"],"optionsEn":["Filing a discrepancy permits all old assumptions to remain unchanged.","A published geological model should never change after new observations.","New evidence should revise dependent judgments rather than merely add a geological photograph."],"answer":2,"explanation":"觀測與決策之間需要明確連結，否則資料很多也無法降低模型風險。 未知條件可導致暫停判斷與補資料，這是工程品質控制的一部分。","explanationEn":"Observations need explicit links to decisions; more data alone do not reduce modeling risk. Unknown conditions can require pausing a judgment and gathering evidence as part of quality control."}}]},{"id":"b103-stage02","order":2,"title":"開挖狀態與施工物流","titleEn":"Excavation states and logistics","description":"以六個相互銜接的練習完成「開挖狀態與施工物流」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on excavation states and logistics, retaining assumptions, diagrams and evidence.","steps":[{"id":"b103-v7-07","sequence":7,"order":1,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-06"],"title":"比較機械掘進與分部開挖概念","titleEn":"Compare mechanized and staged excavation concepts","objective":"理解工法選擇取決於地質、斷面與物流。","objectiveEn":"Understand that methods depend on ground, geometry and logistics.","instruction":"1. 畫機械掘進與分部開挖的概念狀態；2. 比較斷面自由度、設備空間及出碴介面；3. 列出不能從照片推定的條件。","instructionEn":"1. Sketch mechanized and staged excavation concepts; 2. compare geometric flexibility, equipment space and muck interfaces; 3. list conditions that photographs cannot establish.","observation":"設備外觀相似不代表不同地質區段可沿用同一作業設定。","observationEn":"Similar equipment appearance does not justify identical settings in different ground.","failure":"只要使用最大掘進機就能解決所有地質問題。","failureEn":"The largest tunnel-boring machine solves every geological problem.","check":"提交三個工法比較維度與各自資料缺口。","checkEn":"Submit three method-comparison dimensions with evidence gaps.","knowledge":[{"id":"b103-v7-07-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"施工方法是系統選擇，需要處理掌子面、支護、設備與物流的相容性。","textEn":"An excavation method is a system choice involving compatibility among face, support, equipment and logistics."},{"id":"b103-v7-07-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本課程不提供爆破參數或掘進機操作值，只比較公開工法機理。","textEn":"The course provides no blasting parameters or machine settings and compares only public method concepts."}],"quiz":{"question":"審查「比較機械掘進與分部開挖概念」時，哪個判讀有根據？","questionEn":"When reviewing “Compare mechanized and staged excavation concepts”, which interpretation is justified?","options":["設備外觀相似不代表不同地質區段可沿用同一作業設定。","只要使用最大掘進機就能解決所有地質問題。","施工方法只取決於隧道的總長度。"],"optionsEn":["Similar equipment appearance does not justify identical settings in different ground.","The largest tunnel-boring machine solves every geological problem.","Excavation method depends only on total tunnel length."],"answer":0,"explanation":"施工方法是系統選擇，需要處理掌子面、支護、設備與物流的相容性。 本課程不提供爆破參數或掘進機操作值，只比較公開工法機理。","explanationEn":"An excavation method is a system choice involving compatibility among face, support, equipment and logistics. The course provides no blasting parameters or machine settings and compares only public method concepts."}},{"id":"b103-v7-08","sequence":8,"order":2,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-07"],"title":"分辨開挖面與後方工作區","titleEn":"Separate the face from trailing work zones","objective":"把掘進視為串接工序而非單一刀盤。","objectiveEn":"Treat tunnelling as a connected process rather than one cutterhead.","instruction":"1. 畫掌子面、支護及後方輸送三區；2. 標示人、材料與碴料的不同流線；3. 找出一個可能阻塞其他區的介面。","instructionEn":"1. Draw face, support and trailing-conveyor zones; 2. separate people, material and muck flows; 3. identify an interface that can block other zones.","observation":"前端掘進加快若超過後端能力，整體進度未必提高。","observationEn":"Faster advance need not improve progress when downstream capacity is insufficient.","failure":"只提高刀盤理論效率就可保證全隧道工期等比例縮短。","failureEn":"Higher theoretical cutterhead efficiency guarantees proportional schedule reduction.","check":"提交三區流線圖及一個瓶頸說明。","checkEn":"Provide a three-zone flow map and one bottleneck explanation.","knowledge":[{"id":"b103-v7-08-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"串联系統的能力受限制環節影響，停機與交界等待不能在總體模型中省略。","textEn":"A serial system is constrained by limiting stages; downtime and interface waits matter to the overall model."},{"id":"b103-v7-08-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"教學流線只顯示相依關係，不是現地通行或施工配置圖。","textEn":"The teaching flow map shows dependencies, not a field traffic or construction layout."}],"quiz":{"question":"審查「分辨開挖面與後方工作區」時，哪個判讀有根據？","questionEn":"When reviewing “Separate the face from trailing work zones”, which interpretation is justified?","options":["只提高刀盤理論效率就可保證全隧道工期等比例縮短。","前端掘進加快若超過後端能力，整體進度未必提高。","後方輸送能力不會限制前端掘進的總產出。"],"optionsEn":["Higher theoretical cutterhead efficiency guarantees proportional schedule reduction.","Faster advance need not improve progress when downstream capacity is insufficient.","Trailing transport capacity cannot limit overall advance output."],"answer":1,"explanation":"串联系統的能力受限制環節影響，停機與交界等待不能在總體模型中省略。 教學流線只顯示相依關係，不是現地通行或施工配置圖。","explanationEn":"A serial system is constrained by limiting stages; downtime and interface waits matter to the overall model. The teaching flow map shows dependencies, not a field traffic or construction layout."}},{"id":"b103-v7-09","sequence":9,"order":3,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-08"],"title":"拆出臨時支護與永久襯砌","titleEn":"Separate temporary support and final lining","objective":"辨認不同時間狀態下的承載機理。","objectiveEn":"Recognize load-resistance mechanisms at different times.","instruction":"1. 畫剛開挖、初期支護及完成襯砌三狀態；2. 記錄各狀態已存在的構件；3. 比較岩體與結構的相互作用假設。","instructionEn":"1. Draw freshly excavated, initially supported and finally lined states; 2. list components present in each; 3. compare ground–structure interaction assumptions.","observation":"永久襯砌的存在不能回頭證明未完成階段的穩定性。","observationEn":"A final lining does not retrospectively verify stability before its completion.","failure":"將完工襯砌放入所有施工狀態即可簡化而不影響判斷。","failureEn":"Adding the completed lining to every construction state simplifies analysis without consequence.","check":"提交三狀態構件與反力表。","checkEn":"Submit a table of components and reactions for three states.","knowledge":[{"id":"b103-v7-09-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"地下結構與岩體共同變形；支護安裝時機及邊界是模型的一部分。","textEn":"Underground structures and ground deform together; installation timing and boundaries are part of the model."},{"id":"b103-v7-09-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"概念狀態分析不能直接決定現場支護間距或施工時序。","textEn":"Conceptual state analysis cannot directly determine field support spacing or work sequence."}],"quiz":{"question":"審查「拆出臨時支護與永久襯砌」時，哪個判讀有根據？","questionEn":"When reviewing “Separate temporary support and final lining”, which interpretation is justified?","options":["將完工襯砌放入所有施工狀態即可簡化而不影響判斷。","臨時支護的安裝時間不會改變岩體與結構互動。","永久襯砌的存在不能回頭證明未完成階段的穩定性。"],"optionsEn":["Adding the completed lining to every construction state simplifies analysis without consequence.","Temporary-support timing does not affect ground–structure interaction.","A final lining does not retrospectively verify stability before its completion."],"answer":2,"explanation":"地下結構與岩體共同變形；支護安裝時機及邊界是模型的一部分。 概念狀態分析不能直接決定現場支護間距或施工時序。","explanationEn":"Underground structures and ground deform together; installation timing and boundaries are part of the model. Conceptual state analysis cannot directly determine field support spacing or work sequence."}},{"id":"b103-v7-10","sequence":10,"order":4,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-09"],"title":"讀取收斂量測的時間曲線","titleEn":"Interpret convergence time histories","objective":"區分變形速率、總量與量測重置。","objectiveEn":"Distinguish deformation rate, total movement and datum resets.","instruction":"1. 建立三條自設收斂曲線；2. 分別加入趨穩、加速與基準跳點；3. 對每條列出下一個應查證的資料。","instructionEn":"1. Create three synthetic convergence curves; 2. include stabilization, acceleration and a datum jump; 3. specify the next evidence check for each.","observation":"曲線跳點可能來自量測基準變更，需先查紀錄再判斷岩體突變。","observationEn":"A curve jump can result from a datum change and requires record checks before inferring abrupt ground behavior.","failure":"量測跳點必然表示隧道立即發生同等變形。","failureEn":"Every measurement jump necessarily indicates equal immediate tunnel movement.","check":"繳交三曲線的候選解釋及查證表。","checkEn":"Provide candidate explanations and checks for three curves.","knowledge":[{"id":"b103-v7-10-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"變形量及其時間趨勢傳達不同資訊；單一讀數缺少速率與背景。","textEn":"Movement magnitude and time trend convey different information; one reading lacks rate and context."},{"id":"b103-v7-10-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"所有警戒值在本練習都保持未指定，不以自設曲線設定真實工地限值。","textEn":"Alert thresholds remain unspecified; synthetic curves do not establish real construction limits."}],"quiz":{"question":"審查「讀取收斂量測的時間曲線」時，哪個判讀有根據？","questionEn":"When reviewing “Interpret convergence time histories”, which interpretation is justified?","options":["曲線跳點可能來自量測基準變更，需先查紀錄再判斷岩體突變。","量測跳點必然表示隧道立即發生同等變形。","變形總量相同就表示各曲線的速率相同。"],"optionsEn":["A curve jump can result from a datum change and requires record checks before inferring abrupt ground behavior.","Every measurement jump necessarily indicates equal immediate tunnel movement.","Equal total movement implies equal rates in every curve."],"answer":0,"explanation":"變形量及其時間趨勢傳達不同資訊；單一讀數缺少速率與背景。 所有警戒值在本練習都保持未指定，不以自設曲線設定真實工地限值。","explanationEn":"Movement magnitude and time trend convey different information; one reading lacks rate and context. Alert thresholds remain unspecified; synthetic curves do not establish real construction limits."}},{"id":"b103-v7-11","sequence":11,"order":5,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-10"],"title":"建立出碴與材料再利用帳","titleEn":"Create a muck and reuse ledger","objective":"追蹤材料品質、去向與物流守恆。","objectiveEn":"Track material quality, destination and logistics conservation.","instruction":"1. 對自設碴料批次建立重量欄；2. 依待檢、可用、不可用分流；3. 核對庫存變化與運出入是否平衡。","instructionEn":"1. Assign masses to hypothetical muck batches; 2. separate pending, suitable and unsuitable streams; 3. reconcile inventory with inflows and outflows.","observation":"材料數量平衡成立仍不代表每批都適合再利用。","observationEn":"A balanced material ledger does not establish suitability of every batch for reuse.","failure":"所有挖出的岩石都能直接當成同等級混凝土骨材。","failureEn":"Every excavated rock batch can directly serve as equivalent concrete aggregate.","check":"輸出有品質狀態及去向的批次守恆表。","checkEn":"Produce a batch balance with quality status and destinations.","knowledge":[{"id":"b103-v7-11-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"材料再利用需要性質與污染等證據，不能僅依岩石外觀決定用途。","textEn":"Reuse requires property and contamination evidence rather than appearance alone."},{"id":"b103-v7-11-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"庫存、運輸與品質結果是不同資料流，需要共同批次識別碼才能追溯。","textEn":"Inventory, transport and quality results require common batch identifiers for traceability."}],"quiz":{"question":"審查「建立出碴與材料再利用帳」時，哪個判讀有根據？","questionEn":"When reviewing “Create a muck and reuse ledger”, which interpretation is justified?","options":["所有挖出的岩石都能直接當成同等級混凝土骨材。","材料數量平衡成立仍不代表每批都適合再利用。","出碴重量相同就代表所有批次具有相同材料品質。"],"optionsEn":["Every excavated rock batch can directly serve as equivalent concrete aggregate.","A balanced material ledger does not establish suitability of every batch for reuse.","Equal muck masses establish identical quality in every batch."],"answer":1,"explanation":"材料再利用需要性質與污染等證據，不能僅依岩石外觀決定用途。 庫存、運輸與品質結果是不同資料流，需要共同批次識別碼才能追溯。","explanationEn":"Reuse requires property and contamination evidence rather than appearance alone. Inventory, transport and quality results require common batch identifiers for traceability."}},{"id":"b103-v7-12","sequence":12,"order":6,"sourceIds":["v7-gotthard-network","v7-gotthard-geology","v7-gotthard-construction"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-11"],"title":"協調多工作面的共同介面","titleEn":"Coordinate multiple work fronts","objective":"理解平行開挖如何共享基準與資源。","objectiveEn":"Understand shared datums and resources in parallel drives.","instruction":"1. 畫兩個假想工作面與共同出入口；2. 設定共用運輸及測量介面；3. 模擬其中一區延後時的相依影響。","instructionEn":"1. Draw two hypothetical faces and a shared access; 2. define shared transport and survey interfaces; 3. trace consequences when one area is delayed.","observation":"增加工作面會增加並行能力，也可能增加共用資源衝突。","observationEn":"Additional faces increase parallel opportunities but can create shared-resource conflicts.","failure":"工作面數量加倍就一定使完工時間減半。","failureEn":"Doubling work fronts necessarily halves completion time.","check":"提交資源與基準的兩類相依圖。","checkEn":"Provide separate dependency maps for resources and datums.","knowledge":[{"id":"b103-v7-12-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"平行任務需共享可靠的幾何基準，否則速度提升可能累積到貫通誤差。","textEn":"Parallel tasks need reliable shared geometry or faster progress can accumulate breakthrough mismatch."},{"id":"b103-v7-12-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"施工組織比較需考慮資源限制及介面等待，不能只加總理論掘進率。","textEn":"Construction organization must consider resource limits and interface waits, not only theoretical advance rates."}],"quiz":{"question":"審查「協調多工作面的共同介面」時，哪個判讀有根據？","questionEn":"When reviewing “Coordinate multiple work fronts”, which interpretation is justified?","options":["工作面數量加倍就一定使完工時間減半。","平行工作面不需共同測量基準，只需各自前進。","增加工作面會增加並行能力，也可能增加共用資源衝突。"],"optionsEn":["Doubling work fronts necessarily halves completion time.","Parallel work fronts need no shared survey datum, only local advance.","Additional faces increase parallel opportunities but can create shared-resource conflicts."],"answer":2,"explanation":"平行任務需共享可靠的幾何基準，否則速度提升可能累積到貫通誤差。 施工組織比較需考慮資源限制及介面等待，不能只加總理論掘進率。","explanationEn":"Parallel tasks need reliable shared geometry or faster progress can accumulate breakthrough mismatch. Construction organization must consider resource limits and interface waits, not only theoretical advance rates."}}]},{"id":"b103-stage03","order":3,"title":"襯砌、防水與鐵路介面","titleEn":"Lining, waterproofing and railway interfaces","description":"以六個相互銜接的練習完成「襯砌、防水與鐵路介面」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on lining, waterproofing and railway interfaces, retaining assumptions, diagrams and evidence.","steps":[{"id":"b103-v7-13","sequence":13,"order":1,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-12"],"title":"檢查雙向貫通的誤差鏈","titleEn":"Review breakthrough error chains","objective":"理解方向、距離與座標基準的累積。","objectiveEn":"Understand accumulation of direction, distance and reference errors.","instruction":"1. 畫兩端向中間延伸的測線；2. 加入小幅自設角度及距離偏差；3. 比較閉合差並註明同一座標基準。","instructionEn":"1. Draw survey chains advancing from opposite ends; 2. introduce small hypothetical angle and distance errors; 3. compare closure under one reference frame.","observation":"很小的方向偏差沿長距離延伸可能形成明顯橫向閉合差。","observationEn":"A small directional error over a long distance can create substantial lateral closure error.","failure":"只要每段距離量得精確就可忽略方向與座標轉換。","failureEn":"Accurate segment distances make direction and coordinate transformations irrelevant.","check":"輸出兩條誤差鏈及一份閉合差來源表。","checkEn":"Provide two error chains and a closure-error source table.","knowledge":[{"id":"b103-v7-13-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"測量誤差可含系統性與隨機部分，方向偏差不能用距離精度掩蓋。","textEn":"Survey errors include systematic and random components; distance precision does not hide direction bias."},{"id":"b103-v7-13-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"公開地圖座標不是隧道貫通測量基準，本步使用自設平面座標。","textEn":"Public map coordinates are not tunnel breakthrough control; this exercise uses an invented planar frame."}],"quiz":{"question":"審查「檢查雙向貫通的誤差鏈」時，哪個判讀有根據？","questionEn":"When reviewing “Review breakthrough error chains”, which interpretation is justified?","options":["很小的方向偏差沿長距離延伸可能形成明顯橫向閉合差。","只要每段距離量得精確就可忽略方向與座標轉換。","測線方向偏差只影響起點，不會隨距離累積。"],"optionsEn":["A small directional error over a long distance can create substantial lateral closure error.","Accurate segment distances make direction and coordinate transformations irrelevant.","Survey-direction bias affects only the starting point and cannot accumulate with distance."],"answer":0,"explanation":"測量誤差可含系統性與隨機部分，方向偏差不能用距離精度掩蓋。 公開地圖座標不是隧道貫通測量基準，本步使用自設平面座標。","explanationEn":"Survey errors include systematic and random components; distance precision does not hide direction bias. Public map coordinates are not tunnel breakthrough control; this exercise uses an invented planar frame."}},{"id":"b103-v7-14","sequence":14,"order":2,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-13"],"title":"分開滲水來源與排水去向","titleEn":"Separate seepage sources and drainage destinations","objective":"建立水路與結構邊界的概念模型。","objectiveEn":"Build a conceptual model of water paths and structural boundaries.","instruction":"1. 畫岩體、支護、防水層及內襯；2. 用箭頭標示假想滲水；3. 分列清水、可能污染水與未知來源。","instructionEn":"1. Draw ground, support, waterproofing and inner lining; 2. mark hypothetical seepage; 3. separate clean, potentially contaminated and unknown sources.","observation":"不同來源的水應先辨識，不能直接假設具有相同排放條件。","observationEn":"Water sources need identification before assuming identical discharge conditions.","failure":"水都是透明就能合併成同一條無需檢測的排水線。","failureEn":"All clear-looking water can share one untested discharge route.","check":"提交標示未知水源及去向的水路圖。","checkEn":"Submit a water-path diagram with unknown sources and destinations.","knowledge":[{"id":"b103-v7-14-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"地下水、施工用水與污染事件可能需要不同處理，外觀不足以判定品質。","textEn":"Groundwater, process water and contamination events can require different treatment; appearance is insufficient."},{"id":"b103-v7-14-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"防水與排水需協調，堵住可見水路不一定解決上游壓力問題。","textEn":"Waterproofing and drainage must be coordinated; blocking visible flow does not necessarily address upstream pressure."}],"quiz":{"question":"審查「分開滲水來源與排水去向」時，哪個判讀有根據？","questionEn":"When reviewing “Separate seepage sources and drainage destinations”, which interpretation is justified?","options":["水都是透明就能合併成同一條無需檢測的排水線。","不同來源的水應先辨識，不能直接假設具有相同排放條件。","封住可見漏水就能保證上游水壓也消失。"],"optionsEn":["All clear-looking water can share one untested discharge route.","Water sources need identification before assuming identical discharge conditions.","Blocking visible leakage guarantees upstream water pressure disappears."],"answer":1,"explanation":"地下水、施工用水與污染事件可能需要不同處理，外觀不足以判定品質。 防水與排水需協調，堵住可見水路不一定解決上游壓力問題。","explanationEn":"Groundwater, process water and contamination events can require different treatment; appearance is insufficient. Waterproofing and drainage must be coordinated; blocking visible flow does not necessarily address upstream pressure."}},{"id":"b103-v7-15","sequence":15,"order":3,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-14"],"title":"核對襯砌接縫與連通口","titleEn":"Check lining joints and connection openings","objective":"把局部細節視為連續系統的弱點候選。","objectiveEn":"Treat local details as potential discontinuities in a continuous system.","instruction":"1. 畫襯砌、接縫與橫坑開口；2. 標記水、力及電纜三種跨界路徑；3. 列出各自需保留的施工與檢查紀錄。","instructionEn":"1. Draw lining, joints and a cross-passage opening; 2. mark water, force and cable crossings; 3. list installation and inspection records for each.","observation":"連續壁面模型不能自動代表接縫與穿透部位的行為。","observationEn":"A continuous-wall model does not automatically represent joints and penetrations.","failure":"大部分襯砌沒有滲水就能證明每個接縫都具有相同品質。","failureEn":"A mostly dry lining proves identical quality at every joint.","check":"輸出至少三種跨界介面的證據清單。","checkEn":"Provide evidence lists for at least three crossing interfaces.","knowledge":[{"id":"b103-v7-15-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"幾何不連續會改變局部變形、水路及應力分布，因此需要具體細節資料。","textEn":"Geometric discontinuities change local deformation, flow and stresses and require detail-specific evidence."},{"id":"b103-v7-15-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"照片與示意圖有助於定位，但不能代替隱蔽工程及材料紀錄。","textEn":"Photos and schematics locate details but do not replace concealed-work and material records."}],"quiz":{"question":"審查「核對襯砌接縫與連通口」時，哪個判讀有根據？","questionEn":"When reviewing “Check lining joints and connection openings”, which interpretation is justified?","options":["大部分襯砌沒有滲水就能證明每個接縫都具有相同品質。","整段襯砌看似連續即可刪除接縫與開口模型。","連續壁面模型不能自動代表接縫與穿透部位的行為。"],"optionsEn":["A mostly dry lining proves identical quality at every joint.","An apparently continuous lining permits deletion of joint and opening models.","A continuous-wall model does not automatically represent joints and penetrations."],"answer":2,"explanation":"幾何不連續會改變局部變形、水路及應力分布，因此需要具體細節資料。 照片與示意圖有助於定位，但不能代替隱蔽工程及材料紀錄。","explanationEn":"Geometric discontinuities change local deformation, flow and stresses and require detail-specific evidence. Photos and schematics locate details but do not replace concealed-work and material records."}},{"id":"b103-v7-16","sequence":16,"order":4,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-15"],"title":"把軌道幾何連到結構空間","titleEn":"Connect track geometry to structural space","objective":"辨識行車界限、軌道基準與維修空間。","objectiveEn":"Distinguish vehicle clearance, track datums and maintenance space.","instruction":"1. 在隧道斷面畫概念軌道及車輛包絡；2. 另畫架空線與走道；3. 比較軌道偏移對各介面空間的影響。","instructionEn":"1. Draw conceptual track and vehicle envelopes; 2. add overhead equipment and walkways; 3. compare effects of track offsets on interface space.","observation":"隧道淨空合適仍需核對軌道位置與設備包絡的共同條件。","observationEn":"Adequate tunnel size still requires compatible track position and equipment envelopes.","failure":"土建斷面容得下車體就代表全部鐵路設備都可直接安裝。","failureEn":"A civil section containing the vehicle body guarantees fit for all railway equipment.","check":"提供三種包絡及共同基準的斷面圖。","checkEn":"Provide a section with three envelopes and a common datum.","knowledge":[{"id":"b103-v7-16-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"土建及鐵路設備使用同一幾何空間，但各自有安裝、運動與維護需求。","textEn":"Civil works and railway equipment share space but have distinct installation, movement and maintenance needs."},{"id":"b103-v7-16-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本步包絡為教學自繪，不提供真實鐵路通行或設備淨空批准值。","textEn":"Teaching envelopes are original sketches, not approved railway or equipment-clearance values."}],"quiz":{"question":"審查「把軌道幾何連到結構空間」時，哪個判讀有根據？","questionEn":"When reviewing “Connect track geometry to structural space”, which interpretation is justified?","options":["隧道淨空合適仍需核對軌道位置與設備包絡的共同條件。","土建斷面容得下車體就代表全部鐵路設備都可直接安裝。","車輛包絡與設備維修包絡永遠相同。"],"optionsEn":["Adequate tunnel size still requires compatible track position and equipment envelopes.","A civil section containing the vehicle body guarantees fit for all railway equipment.","Vehicle and equipment-maintenance envelopes are always identical."],"answer":0,"explanation":"土建及鐵路設備使用同一幾何空間，但各自有安裝、運動與維護需求。 本步包絡為教學自繪，不提供真實鐵路通行或設備淨空批准值。","explanationEn":"Civil works and railway equipment share space but have distinct installation, movement and maintenance needs. Teaching envelopes are original sketches, not approved railway or equipment-clearance values."}},{"id":"b103-v7-17","sequence":17,"order":5,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-16"],"title":"區分供電、通訊與控制介面","titleEn":"Separate power, communications and control","objective":"理解鐵路營運是多系統整合。","objectiveEn":"Understand railway operation as multisystem integration.","instruction":"1. 畫供電、通訊與列車控制三條功能鏈；2. 標示資訊及能源流向；3. 列出中斷任一鏈時需要查證的狀態。","instructionEn":"1. Draw power, communications and train-control chains; 2. distinguish information and energy flows; 3. list states needing verification if one chain is interrupted.","observation":"通訊連通並不單獨證明電力或列車控制功能可用。","observationEn":"Communication connectivity alone does not establish power or train-control availability.","failure":"所有設備都回應網路訊息就可判定隧道已具備行車條件。","failureEn":"Network responses from every device establish train-operating readiness.","check":"提交三條功能鏈及至少三個交界問題。","checkEn":"Submit three functional chains and at least three interface questions.","knowledge":[{"id":"b103-v7-17-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"子系統可用與系統整合可用是不同層級，必須對應到服務功能。","textEn":"Subsystem availability and integrated readiness are different levels and must map to service functions."},{"id":"b103-v7-17-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"課程只討論功能邊界，不提供真實列車控制配置或現地操作指令。","textEn":"The course discusses functional boundaries, not actual train-control configurations or field commands."}],"quiz":{"question":"審查「區分供電、通訊與控制介面」時，哪個判讀有根據？","questionEn":"When reviewing “Separate power, communications and control”, which interpretation is justified?","options":["所有設備都回應網路訊息就可判定隧道已具備行車條件。","通訊連通並不單獨證明電力或列車控制功能可用。","能源流與資訊流可用同一條線不加區分地驗證。"],"optionsEn":["Network responses from every device establish train-operating readiness.","Communication connectivity alone does not establish power or train-control availability.","Energy and information flows can be verified as one indistinguishable line."],"answer":1,"explanation":"子系統可用與系統整合可用是不同層級，必須對應到服務功能。 課程只討論功能邊界，不提供真實列車控制配置或現地操作指令。","explanationEn":"Subsystem availability and integrated readiness are different levels and must map to service functions. The course discusses functional boundaries, not actual train-control configurations or field commands."}},{"id":"b103-v7-18","sequence":18,"order":6,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-17"],"title":"建立土建移交的證據索引","titleEn":"Create a civil-to-systems handover index","objective":"防止已完工與已適合安裝的概念混淆。","objectiveEn":"Avoid conflating construction completion with installation readiness.","instruction":"1. 列出斷面、滲水、基準及預留介面；2. 為每項配一種紀錄與版本；3. 標記尚未解決、會阻礙設備安裝的缺項。","instructionEn":"1. List geometry, seepage, datums and reserved interfaces; 2. assign a record and version to each; 3. flag unresolved items preventing installation readiness.","observation":"土建完成日期不是每個機電介面已驗證的替代證據。","observationEn":"A civil completion date does not substitute for verified service interfaces.","failure":"開挖貫通就表示所有後續安裝與營運驗證都已完成。","failureEn":"Breakthrough means all installation and operational verification are complete.","check":"繳交可追到位置及版本的移交索引。","checkEn":"Submit a handover index traceable to location and version.","knowledge":[{"id":"b103-v7-18-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"移交將幾何、品質及限制資訊交給下一專業，是功能整合的一部分。","textEn":"Handover transfers geometry, quality and limitations to the next discipline as part of functional integration."},{"id":"b103-v7-18-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"證據應明確標示驗證範圍，不能把一段合格延伸為全線合格。","textEn":"Evidence must state verified scope rather than extend one accepted section to the whole route."}],"quiz":{"question":"審查「建立土建移交的證據索引」時，哪個判讀有根據？","questionEn":"When reviewing “Create a civil-to-systems handover index”, which interpretation is justified?","options":["開挖貫通就表示所有後續安裝與營運驗證都已完成。","移交只需要完成日期，不需要資料位置與版本。","土建完成日期不是每個機電介面已驗證的替代證據。"],"optionsEn":["Breakthrough means all installation and operational verification are complete.","Handover needs only a completion date, not data location and version.","A civil completion date does not substitute for verified service interfaces."],"answer":2,"explanation":"移交將幾何、品質及限制資訊交給下一專業，是功能整合的一部分。 證據應明確標示驗證範圍，不能把一段合格延伸為全線合格。","explanationEn":"Handover transfers geometry, quality and limitations to the next discipline as part of functional integration. Evidence must state verified scope rather than extend one accepted section to the whole route."}}]},{"id":"b103-stage04","order":4,"title":"系統驗證與衍生工程","titleEn":"System verification and related projects","description":"以六個相互銜接的練習完成「系統驗證與衍生工程」，保留假設、圖示與判讀證據。","descriptionEn":"Complete six connected exercises on system verification and related projects, retaining assumptions, diagrams and evidence.","steps":[{"id":"b103-v7-19","sequence":19,"order":1,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-18"],"title":"分開局部試驗與整合試驗","titleEn":"Separate local and integrated tests","objective":"建立從設備功能到服務功能的證據鏈。","objectiveEn":"Build an evidence chain from device function to service function.","instruction":"1. 為一個概念通訊節點列出局部測試；2. 加入跨區端到端情境；3. 標記局部通過仍無法回答的整體問題。","instructionEn":"1. Define a local test for a conceptual communication node; 2. add an end-to-end cross-zone scenario; 3. identify system questions not answered by local success.","observation":"各設備單獨通過並不保證跨系統的功能與時序相容。","observationEn":"Independent device passes do not establish compatible cross-system functions and timing.","failure":"把各廠商測試報告相加即可取代所有整合驗證。","failureEn":"Adding supplier reports replaces every integration test.","check":"提交要求、測試範圍及缺口三欄矩陣。","checkEn":"Provide a requirements, test-scope and gap matrix.","knowledge":[{"id":"b103-v7-19-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"整合驗證針對介面與共同情境，與單體功能試驗具有不同覆蓋範圍。","textEn":"Integration verification covers interfaces and shared scenarios distinct from standalone function tests."},{"id":"b103-v7-19-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"自設案例用於查漏，不宣稱重現哥達隧道的正式驗收程序。","textEn":"Synthetic cases expose gaps and do not reproduce Gotthard’s formal acceptance process."}],"quiz":{"question":"審查「分開局部試驗與整合試驗」時，哪個判讀有根據？","questionEn":"When reviewing “Separate local and integrated tests”, which interpretation is justified?","options":["各設備單獨通過並不保證跨系統的功能與時序相容。","把各廠商測試報告相加即可取代所有整合驗證。","整合試驗只是單體試驗更換名稱，覆蓋範圍完全相同。"],"optionsEn":["Independent device passes do not establish compatible cross-system functions and timing.","Adding supplier reports replaces every integration test.","Integration testing merely renames component testing with identical coverage."],"answer":0,"explanation":"整合驗證針對介面與共同情境，與單體功能試驗具有不同覆蓋範圍。 自設案例用於查漏，不宣稱重現哥達隧道的正式驗收程序。","explanationEn":"Integration verification covers interfaces and shared scenarios distinct from standalone function tests. Synthetic cases expose gaps and do not reproduce Gotthard’s formal acceptance process."}},{"id":"b103-v7-20","sequence":20,"order":2,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-19"],"title":"用非操作方式檢查可達性","titleEn":"Review access without issuing operating instructions","objective":"辨識平面連通與實際可使用的差異。","objectiveEn":"Distinguish drawn connectivity from practical availability.","instruction":"1. 在雙管圖標出概念人員路徑；2. 另列門、照明及資訊需求；3. 以缺少一項資訊的例子說明不能直接判定可達。","instructionEn":"1. Mark conceptual pedestrian routes on the twin-tube diagram; 2. list door, lighting and information needs; 3. show why one missing item prevents an availability judgment.","observation":"圖上路徑連通仍需設備、資訊與狀態證據才能判斷可使用。","observationEn":"A connected path still requires equipment, information and state evidence before judging usability.","failure":"橫坑存在就自動代表任何情境下都可自由通行。","failureEn":"The existence of a cross-passage implies free passage in every scenario.","check":"提交功能需求清單，保留現地程序為未提供。","checkEn":"Submit functional requirements while leaving field procedures unspecified.","knowledge":[{"id":"b103-v7-20-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"可達性包含幾何與狀態；一條線無法表達門、環境及設備可用性。","textEn":"Access includes geometry and state; one line cannot represent doors, environment and equipment availability."},{"id":"b103-v7-20-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"本練習不提供火災、疏散或列車事故處置程序，實務須遵循營運者指引。","textEn":"This exercise supplies no fire, evacuation or train-incident procedure; actual practice follows operator guidance."}],"quiz":{"question":"審查「用非操作方式檢查可達性」時，哪個判讀有根據？","questionEn":"When reviewing “Review access without issuing operating instructions”, which interpretation is justified?","options":["橫坑存在就自動代表任何情境下都可自由通行。","圖上路徑連通仍需設備、資訊與狀態證據才能判斷可使用。","一張平面圖可完整表達門的狀態、照明及設備可用性。"],"optionsEn":["The existence of a cross-passage implies free passage in every scenario.","A connected path still requires equipment, information and state evidence before judging usability.","One plan fully represents door states, lighting and equipment availability."],"answer":1,"explanation":"可達性包含幾何與狀態；一條線無法表達門、環境及設備可用性。 本練習不提供火災、疏散或列車事故處置程序，實務須遵循營運者指引。","explanationEn":"Access includes geometry and state; one line cannot represent doors, environment and equipment availability. This exercise supplies no fire, evacuation or train-incident procedure; actual practice follows operator guidance."}},{"id":"b103-v7-21","sequence":21,"order":3,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-20"],"title":"建立維護窗口的介面問題","titleEn":"Map maintenance-window interface questions","objective":"辨識單一設備維修與鐵路服務之間的依賴。","objectiveEn":"Identify dependencies between equipment maintenance and railway service.","instruction":"1. 選一個假想設備維護項；2. 標出共用供電、通訊及接近路徑；3. 區分設備完成、功能複核及服務恢復三種狀態。","instructionEn":"1. Select a hypothetical equipment-maintenance task; 2. mark shared power, communications and access paths; 3. distinguish task completion, functional recheck and service restoration.","observation":"維修工作結束與整個相關功能已恢復是不同的證據判斷。","observationEn":"Finishing a maintenance task and restoring the associated integrated function are different evidence judgments.","failure":"單一設備修好就能自行判定所有相關鐵路服務已恢復。","failureEn":"Repairing one device independently establishes that every related railway service has been restored.","check":"提交三種狀態及交界證據的相依圖。","checkEn":"Submit a dependency map of three states and interface evidence.","knowledge":[{"id":"b103-v7-21-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"共享資源會使維護影響跨越單一設備邊界，因此應追蹤相關功能。","textEn":"Shared resources let maintenance effects cross device boundaries, so related functions must be traced."},{"id":"b103-v7-21-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"課程只建立工程問題，不指定封鎖、隔離、復電或列車營運程序。","textEn":"The exercise defines engineering questions and specifies no possession, isolation, reenergization or train-operating procedure."}],"quiz":{"question":"審查「建立維護窗口的介面問題」時，哪個判讀有根據？","questionEn":"When reviewing “Map maintenance-window interface questions”, which interpretation is justified?","options":["單一設備修好就能自行判定所有相關鐵路服務已恢復。","共用資源只影響被維護的設備，不會影響相鄰功能。","維修工作結束與整個相關功能已恢復是不同的證據判斷。"],"optionsEn":["Repairing one device independently establishes that every related railway service has been restored.","Shared resources affect only maintained equipment and never adjacent functions.","Finishing a maintenance task and restoring the associated integrated function are different evidence judgments."],"answer":2,"explanation":"共享資源會使維護影響跨越單一設備邊界，因此應追蹤相關功能。 課程只建立工程問題，不指定封鎖、隔離、復電或列車營運程序。","explanationEn":"Shared resources let maintenance effects cross device boundaries, so related functions must be traced. The exercise defines engineering questions and specifies no possession, isolation, reenergization or train-operating procedure."}},{"id":"b103-v7-22","sequence":22,"order":4,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-21"],"title":"比較缺陷、環境與感測器異常","titleEn":"Compare defects, environment and sensor anomalies","objective":"為維護觀察保留多個候選解釋。","objectiveEn":"Retain multiple explanations for maintenance observations.","instruction":"1. 自設一段滲水及位移紀錄；2. 加入感測器維修與降雨時間；3. 分列可能關係、尚未證實關係及補測需求。","instructionEn":"1. Create synthetic seepage and movement records; 2. add sensor-service and rainfall times; 3. separate possible relations, unproven relations and further evidence.","observation":"同時發生的變化只能提出關聯假說，不能直接證明單一成因。","observationEn":"Coincident changes suggest a relationship but do not prove a single cause.","failure":"降雨後讀數改變便能排除所有設備與基準因素。","failureEn":"A post-rainfall change excludes every equipment and datum explanation.","check":"輸出至少三項候選原因的證據評分表。","checkEn":"Provide an evidence table for at least three candidate causes.","knowledge":[{"id":"b103-v7-22-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"因果判讀需要時間、空間及獨立證據一致；單一相關不足以診斷。","textEn":"Causal interpretation needs consistent temporal, spatial and independent evidence; correlation alone is insufficient."},{"id":"b103-v7-22-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"維護資料的缺漏與感測器更換必須保留在時間軸上，避免假趨勢。","textEn":"Data gaps and sensor replacements belong on the timeline to avoid false trends."}],"quiz":{"question":"審查「比較缺陷、環境與感測器異常」時，哪個判讀有根據？","questionEn":"When reviewing “Compare defects, environment and sensor anomalies”, which interpretation is justified?","options":["同時發生的變化只能提出關聯假說，不能直接證明單一成因。","降雨後讀數改變便能排除所有設備與基準因素。","兩條曲線同時變動足以證明其中一條必然造成另一條。"],"optionsEn":["Coincident changes suggest a relationship but do not prove a single cause.","A post-rainfall change excludes every equipment and datum explanation.","Simultaneous changes prove one curve necessarily causes the other."],"answer":0,"explanation":"因果判讀需要時間、空間及獨立證據一致；單一相關不足以診斷。 維護資料的缺漏與感測器更換必須保留在時間軸上，避免假趨勢。","explanationEn":"Causal interpretation needs consistent temporal, spatial and independent evidence; correlation alone is insufficient. Data gaps and sensor replacements belong on the timeline to avoid false trends."}},{"id":"b103-v7-23","sequence":23,"order":5,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-22"],"title":"比較海峽、山岳與都市隧道","titleEn":"Compare strait, mountain and urban tunnels","objective":"找出哥達、英法與雪山隧道可互學的問題。","objectiveEn":"Identify transferable questions among Gotthard, Channel and Hsuehshan tunnels.","instruction":"1. 查各隧道用途與場址；2. 比較水、地質、運輸及連通需求；3. 列出共同的證據管理方法與不可沿用的參數。","instructionEn":"1. Verify each tunnel’s use and setting; 2. compare water, geology, transport and connection requirements; 3. separate shared evidence methods from nontransferable parameters.","observation":"地質更新及介面追溯可互學，但鐵路與公路的營運需求不同。","observationEn":"Geological updating and interface traceability transfer, but rail and road operational requirements differ.","failure":"都是長隧道就可套用同一通風、斷面與行車模型。","failureEn":"All long tunnels can share the same ventilation, section and traffic model.","check":"提交三隧道的相似處與差異表。","checkEn":"Provide a three-tunnel similarity and difference table.","knowledge":[{"id":"b103-v7-23-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"工程比較要保持系統邊界清楚，不能把隧道長度當成唯一難度指標。","textEn":"Comparisons need clear system boundaries and cannot use length as the sole complexity measure."},{"id":"b103-v7-23-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"延伸研究應從各營運者與業主資料重新建模，而非將本課程假設直接複製。","textEn":"Related research should rebuild from operator and owner evidence rather than copy this course’s assumptions."}],"quiz":{"question":"審查「比較海峽、山岳與都市隧道」時，哪個判讀有根據？","questionEn":"When reviewing “Compare strait, mountain and urban tunnels”, which interpretation is justified?","options":["都是長隧道就可套用同一通風、斷面與行車模型。","地質更新及介面追溯可互學，但鐵路與公路的營運需求不同。","公路與鐵路隧道可直接共用全部營運假設。"],"optionsEn":["All long tunnels can share the same ventilation, section and traffic model.","Geological updating and interface traceability transfer, but rail and road operational requirements differ.","Road and railway tunnels can directly reuse every operating assumption."],"answer":1,"explanation":"工程比較要保持系統邊界清楚，不能把隧道長度當成唯一難度指標。 延伸研究應從各營運者與業主資料重新建模，而非將本課程假設直接複製。","explanationEn":"Comparisons need clear system boundaries and cannot use length as the sole complexity measure. Related research should rebuild from operator and owner evidence rather than copy this course’s assumptions."}},{"id":"b103-v7-24","sequence":24,"order":6,"sourceIds":["v7-gotthard-geology","v7-gotthard-construction","v7-gotthard-technical"],"simulationOnly":true,"estimatedMinutes":25,"prerequisiteIds":["b103-v7-23"],"title":"交付隧道系統學習檔案","titleEn":"Deliver the tunnel-system learning dossier","objective":"把地質到鐵路服務串成可追溯鏈。","objectiveEn":"Connect geology to railway service through a traceable chain.","instruction":"1. 整合路線、地質、狀態及系統圖；2. 每個判讀連接來源與假設；3. 用一項地質變更重新追查下游影響。","instructionEn":"1. Integrate route, geology, state and system diagrams; 2. link each interpretation to sources and assumptions; 3. trace downstream impacts of one ground-model change.","observation":"可追溯檔案能指出證據改變後哪些結論需重驗。","observationEn":"A traceable dossier identifies conclusions requiring recheck after evidence changes.","failure":"所有課程步驟打勾就代表真實隧道具備營運安全認證。","failureEn":"Checking every lesson step certifies an actual tunnel’s operational safety.","check":"繳交四階段索引、未解問題與一次修訂演練。","checkEn":"Submit a four-stage index, unresolved questions and one revision exercise.","knowledge":[{"id":"b103-v7-24-k1","title":"機理與邊界","titleEn":"Mechanism and boundary","text":"隧道是地盤、結構、設備及營運共同組成的系統，驗證必須跨越專業邊界。","textEn":"A tunnel combines ground, structures, equipment and operations, so verification crosses disciplinary boundaries."},{"id":"b103-v7-24-k2","title":"證據與推論","titleEn":"Evidence and inference","text":"學習完成表示已建立概念與證據組織，不表示具備現地挖掘或營運權限。","textEn":"Completion demonstrates conceptual and evidence organization, not permission for field excavation or operation."}],"quiz":{"question":"審查「交付隧道系統學習檔案」時，哪個判讀有根據？","questionEn":"When reviewing “Deliver the tunnel-system learning dossier”, which interpretation is justified?","options":["所有課程步驟打勾就代表真實隧道具備營運安全認證。","新證據不應改變先前已完成的任何模型結論。","可追溯檔案能指出證據改變後哪些結論需重驗。"],"optionsEn":["Checking every lesson step certifies an actual tunnel’s operational safety.","New evidence should never change a previously completed model conclusion.","A traceable dossier identifies conclusions requiring recheck after evidence changes."],"answer":2,"explanation":"隧道是地盤、結構、設備及營運共同組成的系統，驗證必須跨越專業邊界。 學習完成表示已建立概念與證據組織，不表示具備現地挖掘或營運權限。","explanationEn":"A tunnel combines ground, structures, equipment and operations, so verification crosses disciplinary boundaries. Completion demonstrates conceptual and evidence organization, not permission for field excavation or operation."}}]}],"curriculumVersion":7}};
